            "intro": "<div style='font-size: 1.2rem; font-weight: bold; margin-top: 1.5rem; color: black;'>[A Village of Stars] (オリジナル類題)</div> 本文は、ニュージーランドのテカポ (Tekapo) という村についての説明です。この村は、近代化の中で「明るさ」よりも「星空の美しさ」を守ることを選んだユニークな事例です。",
